def choisir_representation(type_probleme):
    if type_probleme in ("addition", "soustraction", "comparaison"):
        return "barres"
    elif type_probleme == "partage":
        return "dessin"
    else:
        return "inconnu"

# Exemple d'utilisation
print(choisir_representation("addition"))   # affiche barres
print(choisir_representation("partage"))    # affiche dessin
